{
  "name": "仪器服务器订阅客户端",
  "name_en": "Instrument Server Subscription Client",
  "manufacturer": "",
  "description": "这是一个非实体的软件客户端组件，用于实验控制系统中连接远程仪器服务器、订阅实时参数更新，并通过代理对象访问远程仪器、模块和参数。它主要用于参数监视、快照获取、远程调用以及参数配置的保存与加载，而不是直接驱动物理仪器硬件。",
  "description_en": "This is a non-physical software client component for connecting to a remote instrument server, subscribing to real-time parameter updates, and accessing remote instruments, modules, and parameters through proxy objects. It is mainly used for parameter monitoring, snapshot retrieval, remote calls, and saving/loading parameter configurations, rather than directly controlling physical hardware.",
  "actions": [
    {
      "action_name": "auto-connect",
      "description": "连接到服务器广播通道并开始订阅指定仪器的实时参数更新。",
      "description_en": "Connect to the server broadcast channel and start subscribing to real-time parameter updates for specified instruments."
    },
    {
      "action_name": "auto-stop",
      "description": "停止订阅监听循环并优雅地结束客户端监听。",
      "description_en": "Stop the subscription listener loop and gracefully terminate client listening."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开订阅客户端连接；为停止监听提供兼容别名。",
      "description_en": "Disconnect the subscription client; a backward-compatible alias for stopping the listener."
    },
    {
      "action_name": "auto-initKwargsFromBluePrint",
      "description": "根据远程对象蓝图初始化代理对象所需的构造参数。",
      "description_en": "Initialize proxy-construction keyword arguments from a remote object blueprint."
    },
    {
      "action_name": "auto-askServer",
      "description": "向服务器发送通用请求并获取响应。",
      "description_en": "Send a generic request to the server and receive a response."
    },
    {
      "action_name": "auto-get_snapshot",
      "description": "获取远程仪器、模块或参数对象的当前快照信息。",
      "description_en": "Retrieve a current snapshot of a remote instrument, module, or parameter object."
    },
    {
      "action_name": "auto-update",
      "description": "更新本地代理中的远程状态或参数信息。",
      "description_en": "Update remote state or parameter information in the local proxy."
    },
    {
      "action_name": "auto-set_parameters",
      "description": "批量设置远程参数的值。",
      "description_en": "Set multiple remote parameter values in a batch."
    },
    {
      "action_name": "auto-add_parameter",
      "description": "向远程对象或代理结构中添加参数。",
      "description_en": "Add a parameter to a remote object or proxy structure."
    },
    {
      "action_name": "auto-remove_parameter",
      "description": "从远程对象或代理结构中移除参数。",
      "description_en": "Remove a parameter from a remote object or proxy structure."
    },
    {
      "action_name": "auto-list_instruments",
      "description": "列出服务器上可用的远程仪器对象。",
      "description_en": "List available remote instrument objects on the server."
    },
    {
      "action_name": "auto-find_or_create_instrument",
      "description": "查找已有远程仪器，或在服务器上创建新的仪器对象。",
      "description_en": "Find an existing remote instrument or create a new instrument object on the server."
    },
    {
      "action_name": "auto-close_instrument",
      "description": "关闭服务器上的远程仪器对象。",
      "description_en": "Close a remote instrument object on the server."
    },
    {
      "action_name": "auto-call",
      "description": "调用远程对象的方法。",
      "description_en": "Call a method on a remote object."
    },
    {
      "action_name": "auto-get_instrument",
      "description": "获取指定远程仪器的代理对象。",
      "description_en": "Get a proxy object for a specified remote instrument."
    },
    {
      "action_name": "auto-getBluePrint",
      "description": "获取远程仪器或模块的蓝图描述信息。",
      "description_en": "Get the blueprint description of a remote instrument or module."
    },
    {
      "action_name": "auto-invalidateBlueprint",
      "description": "使缓存的蓝图失效，以便重新获取最新结构信息。",
      "description_en": "Invalidate a cached blueprint so the latest structural information can be fetched again."
    },
    {
      "action_name": "auto-getParamDict",
      "description": "获取参数字典形式的配置或当前值信息。",
      "description_en": "Get parameter information as a dictionary of configuration or current values."
    },
    {
      "action_name": "auto-paramsToFile",
      "description": "将参数配置导出到文件。",
      "description_en": "Export parameter configurations to a file."
    },
    {
      "action_name": "auto-setParameters",
      "description": "通过兼容接口批量设置远程参数。",
      "description_en": "Set multiple remote parameters through a compatibility-style interface."
    },
    {
      "action_name": "auto-paramsFromFile",
      "description": "从文件读取参数配置并导入到远程对象或代理中。",
      "description_en": "Read parameter configurations from a file and import them into a remote object or proxy."
    },
    {
      "action_name": "auto-get_parameters",
      "description": "获取一个或多个远程参数的当前信息。",
      "description_en": "Get current information for one or more remote parameters."
    },
    {
      "action_name": "auto-save_parameters",
      "description": "保存参数配置，便于后续恢复或复现实验设置。",
      "description_en": "Save parameter configurations for later restoration or experiment reproduction."
    },
    {
      "action_name": "auto-load_parameters",
      "description": "加载已保存的参数配置并应用到远程对象。",
      "description_en": "Load saved parameter configurations and apply them to remote objects."
    }
  ],
  "tag_hints": [
    "instrument server client",
    "real-time parameter subscription",
    "remote instrument proxy",
    "Qt client",
    "snapshot retrieval",
    "parameter configuration persistence",
    "networked lab control"
  ]
}

